bool parse_import_ptr(struct MACH0_(obj_t)* bin, struct reloc_t* reloc, int idx) {
    if (idx < 0 || idx >= bin->sym_count) {
        return false;
    }

    uint8_t descriptor = (bin->sym_table + idx)->n_desc & 0x00ff;
    uint8_t type = (bin->sym_table + idx)->n_desc >> 8;

    if (type != N_UNDF || (descriptor & 0x0001) != 0) {
        return false;
    }

    if (bin->header->cputype == CPU_TYPE_X86_64) {
        reloc->type = R_X86_64_COPY;
    } else {
        reloc->type = R_386_32;
    }

    for (size_t i = 0; i < bin->section_count; i++) {
        struct section_t* section = bin->sections + i;
        if (section->indirect_symbol == idx) {
            reloc->offset = section->offset;
            reloc->addr = section->addr;
            return true;
        }
    }

    return false;
}

bool parse_import_ptr(struct MACH0_(obj_t)* bin, struct reloc_t* reloc, int idx) {
    if (idx < 0 || idx >= bin->symbol_count) {
        return false;
    }

    uint8_t descriptor = (bin->symtab->symbase[idx].n_desc & 0x0ff) >> 8;
    if (descriptor != N_POINTOFIMPORT)
        return false;

    if (bin->header->cputype == CPU_TYPE_X86 || bin->header->cputype == CPU_TYPE_I386) {
        reloc->type = R_386_32;
    }
    else if (bin->header->cputype == CPU_TYPE_X86_64) {
        reloc->type = R_X86_64_32;
    }
    else {
        return false;
    }

    for (uint32_t i = 0; i < bin->header->nsects; i++) {
        struct section_t* sect = &bin->sections[i];
        if (sect->type == S_LAZY_SYMBOL_POINTER || sect->type == S_NON_LAZY_SYMBOL_POINTER) {
            reloc->offset = sect->offset + idx * bin->address_size;
            reloc->address = sect->addr + idx * bin->address_size;
            return true;
        }
    }

    return false;
}

bool parse_import_ptr(struct MACH0_(obj_t)* bin, struct reloc_t* reloc, int idx) {
    if (idx < 0 || idx >= bin->sym_count) {
        return false;
    }

    uint8_t descriptor = (bin->sym_table + idx)->n_desc & 0x0ff;
    bool is_64_bit = bin->is_64_bit;
    reloc->type = is_64_bit ? R_X86_64_PC32 : R_386_32;

    for (uint32_t i = 0; i < bin->section_count; ++i) {
        struct section_t* section = bin->sections[i];
        if (section->indirect_sym_index != 0 && idx == section->indirect_sym_index) {
            reloc->offset = section->offset + idx;
            reloc->addr = section->addr + idx;
            return true;
        }
    }

    return false;
}

bool parse_import_pointer(struct MACH0_(obj_t)* bin, struct reloc_t* reloc, int idx) {
    if (idx < 0 || idx >= bin->symtab->nsyms) {
        return false;
    }

    struct symbol_t* sym = &bin->symtab->syms[idx];
    uint8_t descriptor = sym->descriptor;

    if (descriptor & 0x80) {
        return false;
    }

    if (descriptor & 0x8) {
        reloc->type = R_MACHO_IMPORT32;
    } else {
        reloc->type = R_MACHO_IMPORT64;
    }

    for (size_t i = 0; i < bin->obj->num_sections; i++) {
        struct section_t* sec = &bin->obj->sections[i];
        if (sec->indirect_symbol == idx) {
            reloc->offset = sec->offset;
            reloc->addr = sec->addr;
            return true;
        }
    }

    return false;
}

bool parse_import_ptr(struct MACH0_(obj_t)* bin, struct reloc_t* reloc, int idx) {
    if (idx < 0 || idx >= bin->symbol_count) {
        return false;
    }

    uint8_t desc = bin->symbol_table[idx].n_desc;
    bool is_64_bit = (desc & 0xf0) != 0;

    if (is_64_bit) {
        reloc->type = RELOC_TYPE_64;
    } else {
        reloc->type = RELOC_TYPE_32;
    }

    for (size_t i = 0; i < bin->section_count; ++i) {
        if (bin->sections[i].indirect_symbol_idx == idx) {
            reloc->offset = bin->sections[i].offset;
            reloc->addr = bin->sections[i].addr;
            return true;
        }
    }

    return false;
}
